CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,phone TEXT,role TEXT NOT NULL CHECK(role IN('customer','driver','admin')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS drivers(id INTEGER PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id),vehicle_id INTEGER,status TEXT NOT NULL DEFAULT 'OFFLINE' CHECK(status IN('OFFLINE','AVAILABLE','BUSY')),current_latitude REAL,current_longitude REAL,rating REAL DEFAULT 5,is_active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY,driver_id INTEGER REFERENCES drivers(id),vehicle_type TEXT,brand TEXT,plate_number TEXT);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES users(id),driver_id INTEGER REFERENCES drivers(id),pickup_latitude REAL,pickup_longitude REAL,pickup_address TEXT,destination_latitude REAL,destination_longitude REAL,destination_address TEXT,distance_km REAL,estimated_duration INTEGER,estimated_price INTEGER,final_price INTEGER,status TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE TABLE IF NOT EXISTS ratings(id INTEGER PRIMARY KEY,order_id INTEGER UNIQUE REFERENCES orders(id),customer_id INTEGER REFERENCES users(id),driver_id INTEGER REFERENCES drivers(id),rating INTEGER CHECK(rating BETWEEN 1 AND 5),review TEXT);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),amount INTEGER,method TEXT DEFAULT 'CASH',status TEXT DEFAULT 'PAID',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),label TEXT,address TEXT,latitude REAL,longitude REAL);
CREATE TABLE IF NOT EXISTS tariffs(id INTEGER PRIMARY KEY,base_fare INTEGER,price_per_km INTEGER,minimum_fare INTEGER,radius_km REAL,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS chats(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),sender_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_chats_order ON chats(order_id);
